import{_ as e,a as r,c as t,ac as s}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"小学一年级数学：独立习题集 · 上下、前后、左右与参照物至重复规律与数列初步","description":"18 个知识点、36 道小学一年级练习，每题提供默认折叠的答案、步骤和易错说明。","frontmatter":{"title":"小学一年级数学：独立习题集 · 上下、前后、左右与参照物至重复规律与数列初步","description":"18 个知识点、36 道小学一年级练习，每题提供默认折叠的答案、步骤和易错说明。","splitFrom":"life/math/primary/grade-1/exercises.md","showdocs":{"topics":[{"id":"math","title":"数学","link":"/topics/math/"}],"kind":"习题与解析","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"小学一年级数学：独立习题集","summary":"18 个知识点、36 道小学一年级练习，每题提供默认折叠的答案、步骤和易错说明。","status":"active","related":[{"title":"八年级数学公式速查","link":"/life/math/junior/grade-8/formulas","kind":"公式与参考","scope":"general","audience":"general"},{"title":"八年级数学知识讲解","link":"/life/math/junior/grade-8/knowledge","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 等腰三角形与垂直平分线至加权平均数与方差","link":"/life/math/junior/grade-8/knowledge-part-02","kind":"知识讲解","scope":"general","audience":"general"},{"title":"八年级数学知识讲解 · 平方根、立方根与实数至三角形全等与对应关系","link":"/life/math/junior/grade-8/knowledge-part-01","kind":"知识讲解","scope":"general","audience":"general"},{"title":"程序员数学 01：从编程问题选择学习路线","link":"/life/math/programmer/overview","kind":"知识讲解","scope":"general","audience":"general"}],"prev":{"text":"小学一年级数学：独立习题集 · 数数、基数与序数至求差与多几、少几问题","link":"/life/math/primary/grade-1/exercises-part-01"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"小学一年级数学：独立习题集 · 数数、基数与序数至求差与多几、少几问题","link":"/life/math/primary/grade-1/exercises-part-01"},"next":false},"headers":[],"relativePath":"life/math/primary/grade-1/exercises-part-02.md","filePath":"life/math/primary/grade-1/exercises-part-02.md"}'),p={name:"life/math/primary/grade-1/exercises-part-02.md"};function o(l,a,i,n,d,m){return r(),t("div",null,[...a[0]||(a[0]=[s('<h1 id="小学一年级数学-独立习题集-·-上下、前后、左右与参照物至重复规律与数列初步" tabindex="-1">小学一年级数学：独立习题集 · 上下、前后、左右与参照物至重复规律与数列初步 <a class="header-anchor" href="#小学一年级数学-独立习题集-·-上下、前后、左右与参照物至重复规律与数列初步" aria-label="Permalink to &quot;小学一年级数学：独立习题集 · 上下、前后、左右与参照物至重复规律与数列初步&quot;">​</a></h1><p><a href="/life/math/primary/grade-1/exercises">返回分篇目录</a></p><p><a href="/life/math/primary/grade-1/knowledge">知识讲解</a> · <a href="/life/math/primary/grade-1/formulas">公式速查</a> · <a href="/life/math/primary/grade-1/exercises">独立习题集</a></p><p>按六三三学段编排的通用建议学习顺序；不同地区、教材和学期安排存在差异。本版覆盖以下明确列出的知识点，不将其等同于所有教材或完整课程标准。</p><h2 id="p1-11" tabindex="-1">上下、前后、左右与参照物 <a class="header-anchor" href="#p1-11" aria-label="Permalink to &quot;上下、前后、左右与参照物 {#p1-11}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-11">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-11">公式规则</a></p><h3 id="q21" tabindex="-1">题 21 <a class="header-anchor" href="#q21" aria-label="Permalink to &quot;题 21 {#q21}&quot;">​</a></h3><p>三本书从左到右依次是语文、数学、美术。数学书在语文书的哪一侧？在美术书的哪一侧？</p><p>知识点：p1-11 上下、前后、左右与参照物。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 在语文书右侧，在美术书左侧。</p><p><strong>推导步骤：</strong> 固定题目给定的从左向右方向；数学处在中间，因此相对两本书的方向相反。</p><p><strong>易错提醒：</strong> 同一物体相对不同参照物可以有不同位置描述。</p></details><h3 id="q22" tabindex="-1">题 22 <a class="header-anchor" href="#q22" aria-label="Permalink to &quot;题 22 {#q22}&quot;">​</a></h3><p>书架上层放字典，中层放故事书，下层放画册。故事书在字典和画册的什么位置？</p><p>知识点：p1-11 上下、前后、左右与参照物。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 在字典下方，在画册上方。</p><p><strong>推导步骤：</strong> 依次读取上、中、下三层，故事书所在中层低于字典而高于画册。</p><p><strong>易错提醒：</strong> “上方”与“下方”必须说明相对哪件物品。</p></details><h2 id="p1-12" tabindex="-1">认识平面图形与拼组 <a class="header-anchor" href="#p1-12" aria-label="Permalink to &quot;认识平面图形与拼组 {#p1-12}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-12">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-12">公式规则</a></p><h3 id="q23" tabindex="-1">题 23 <a class="header-anchor" href="#q23" aria-label="Permalink to &quot;题 23 {#q23}&quot;">​</a></h3><p>一个图形有 3 条直边，首尾相连围成一圈，它是什么图形？有几个顶点？</p><p>知识点：p1-12 认识平面图形与拼组。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 三角形；3 个顶点。</p><p><strong>推导步骤：</strong> 三条直边围成的封闭平面图形是三角形；每相邻两边相接形成一个顶点。</p><p><strong>易错提醒：</strong> 三条线段若没有围成封闭图形，不一定构成三角形。</p></details><h3 id="q24" tabindex="-1">题 24 <a class="header-anchor" href="#q24" aria-label="Permalink to &quot;题 24 {#q24}&quot;">​</a></h3><p>两张边长相同的正方形卡片，沿一整条边拼在一起且不重叠，拼成的外轮廓是什么图形？</p><p>知识点：p1-12 认识平面图形与拼组。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 长方形。</p><p><strong>推导步骤：</strong> 拼接后长为原边长的 2 倍，宽为原边长；外轮廓有 4 条直边和 4 个直角。</p><p><strong>易错提醒：</strong> 中间接缝不是外轮廓的一条边。</p></details><h2 id="p1-13" tabindex="-1">认识立体图形与表面 <a class="header-anchor" href="#p1-13" aria-label="Permalink to &quot;认识立体图形与表面 {#p1-13}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-13">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-13">公式规则</a></p><h3 id="q25" tabindex="-1">题 25 <a class="header-anchor" href="#q25" aria-label="Permalink to &quot;题 25 {#q25}&quot;">​</a></h3><p>一个积木六个面都是大小相同的正方形，它属于哪一种常见立体图形？</p><p>知识点：p1-13 认识立体图形与表面。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 正方体。</p><p><strong>推导步骤：</strong> 依据六个面均为相同正方形这一特征判断；不是只看某一个面。</p><p><strong>易错提醒：</strong> 有一个正方形面不能单独证明它是正方体。</p></details><h3 id="q26" tabindex="-1">题 26 <a class="header-anchor" href="#q26" aria-label="Permalink to &quot;题 26 {#q26}&quot;">​</a></h3><p>把圆柱形纸筒竖着放在纸上描底面，得到的是平面图形还是立体图形？是什么形状？</p><p>知识点：p1-13 认识立体图形与表面。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 平面图形，是圆。</p><p><strong>推导步骤：</strong> 描出来的是底面的边界，位于纸面；纸筒整体才是圆柱。</p><p><strong>易错提醒：</strong> 区分物体与物体表面的图形。</p></details><h2 id="p1-14" tabindex="-1">长度比较与厘米测量 <a class="header-anchor" href="#p1-14" aria-label="Permalink to &quot;长度比较与厘米测量 {#p1-14}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-14">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-14">公式规则</a></p><h3 id="q27" tabindex="-1">题 27 <a class="header-anchor" href="#q27" aria-label="Permalink to &quot;题 27 {#q27}&quot;">​</a></h3><p>一根线段从尺上的 0 厘米刻度延伸到 8 厘米刻度。它长多少厘米？</p><p>知识点：p1-14 长度比较与厘米测量。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 8 厘米。</p><p><strong>推导步骤：</strong> 起点是 0，终点是 8，8−0＝8。</p><p><strong>易错提醒：</strong> 读的是厘米刻度，不是数尺上的刻度线条数。</p></details><h3 id="q28" tabindex="-1">题 28 <a class="header-anchor" href="#q28" aria-label="Permalink to &quot;题 28 {#q28}&quot;">​</a></h3><p>一块橡皮两端分别对准 3 厘米和 7 厘米刻度，它长多少厘米？</p><p>知识点：p1-14 长度比较与厘米测量。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 4 厘米。</p><p><strong>推导步骤：</strong> 数 3 到 7 之间的 4 个一厘米间隔，或算 7−3＝4。</p><p><strong>易错提醒：</strong> 不能写成 7 厘米。</p></details><h2 id="p1-15" tabindex="-1">整时、半时与先后 <a class="header-anchor" href="#p1-15" aria-label="Permalink to &quot;整时、半时与先后 {#p1-15}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-15">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-15">公式规则</a></p><h3 id="q29" tabindex="-1">题 29 <a class="header-anchor" href="#q29" aria-label="Permalink to &quot;题 29 {#q29}&quot;">​</a></h3><p>钟面分针指向 12，时针指向 7，表示几时？</p><p>知识点：p1-15 整时、半时与先后。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 7 时。</p><p><strong>推导步骤：</strong> 分针指 12 表示 0 分，时针指 7，因此是 7 时整。</p><p><strong>易错提醒：</strong> 时针与分针不能认反。</p></details><h3 id="q30" tabindex="-1">题 30 <a class="header-anchor" href="#q30" aria-label="Permalink to &quot;题 30 {#q30}&quot;">​</a></h3><p>小芳上午 9 时开始画画，上午 10 时结束，共画了多长时间？</p><p>知识点：p1-15 整时、半时与先后。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 1 小时。</p><p><strong>推导步骤：</strong> 两个时间在同一上午且都是整时，10−9＝1。</p><p><strong>易错提醒：</strong> “10 时”是时刻，“1 小时”是经过的时间。</p></details><h2 id="p1-16" tabindex="-1">人民币元、角、分 <a class="header-anchor" href="#p1-16" aria-label="Permalink to &quot;人民币元、角、分 {#p1-16}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-16">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-16">公式规则</a></p><h3 id="q31" tabindex="-1">题 31 <a class="header-anchor" href="#q31" aria-label="Permalink to &quot;题 31 {#q31}&quot;">​</a></h3><p>2 元 3 角一共是多少角？</p><p>知识点：p1-16 人民币元、角、分。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 23 角。</p><p><strong>推导步骤：</strong> 2 元＝20 角，再加 3 角，得 23 角。</p><p><strong>易错提醒：</strong> 不能把 2 与 3 直接相加得到 5 角。</p></details><h3 id="q32" tabindex="-1">题 32 <a class="header-anchor" href="#q32" aria-label="Permalink to &quot;题 32 {#q32}&quot;">​</a></h3><p>一块橡皮售价 6 角，付给售货员 1 元，应找回多少角？</p><p>知识点：p1-16 人民币元、角、分。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 4 角。</p><p><strong>推导步骤：</strong> 先把 1 元换成 10 角，再算 10−6＝4 角。</p><p><strong>易错提醒：</strong> 单位统一后再减。</p></details><h2 id="p1-17" tabindex="-1">分类、计数与简单统计 <a class="header-anchor" href="#p1-17" aria-label="Permalink to &quot;分类、计数与简单统计 {#p1-17}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-17">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-17">公式规则</a></p><h3 id="q33" tabindex="-1">题 33 <a class="header-anchor" href="#q33" aria-label="Permalink to &quot;题 33 {#q33}&quot;">​</a></h3><p>袋里有红珠 5 颗、蓝珠 3 颗、黄珠 2 颗。按颜色分类后共有几类、多少颗珠子？</p><p>知识点：p1-17 分类、计数与简单统计。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 3 类，共 10 颗。</p><p><strong>推导步骤：</strong> 颜色有红、蓝、黄三种；5＋3＋2＝10。</p><p><strong>易错提醒：</strong> 类别数量与珠子的总数量不同。</p></details><h3 id="q34" tabindex="-1">题 34 <a class="header-anchor" href="#q34" aria-label="Permalink to &quot;题 34 {#q34}&quot;">​</a></h3><p>调查小组最喜欢的水果，每人只选一种：苹果 6 人、香蕉 4 人。哪种人数更多，多几人？</p><p>知识点：p1-17 分类、计数与简单统计。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 苹果更多，多 2 人。</p><p><strong>推导步骤：</strong> 比较 6 与 4，再算 6−4＝2。</p><p><strong>易错提醒：</strong> “每人只选一种”保证这两个类别不重复计人。</p></details><h2 id="p1-18" tabindex="-1">重复规律与数列初步 <a class="header-anchor" href="#p1-18" aria-label="Permalink to &quot;重复规律与数列初步 {#p1-18}&quot;">​</a></h2><p><a href="/life/math/primary/grade-1/knowledge#p1-18">复习讲解</a> · <a href="/life/math/primary/grade-1/formulas#p1-18">公式规则</a></p><h3 id="q35" tabindex="-1">题 35 <a class="header-anchor" href="#q35" aria-label="Permalink to &quot;题 35 {#q35}&quot;">​</a></h3><p>按“红、黄、蓝”不断重复摆珠子。前 6 颗依次是红、黄、蓝、红、黄、蓝，第 7 颗是什么颜色？</p><p>知识点：p1-18 重复规律与数列初步。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 红色。</p><p><strong>推导步骤：</strong> 每 3 颗一组，第 6 颗刚好结束第二组，第 7 颗开始新的一组。</p><p><strong>易错提醒：</strong> 第 7 颗不是沿颜色名称随意轮换，要保持原顺序。</p></details><h3 id="q36" tabindex="-1">题 36 <a class="header-anchor" href="#q36" aria-label="Permalink to &quot;题 36 {#q36}&quot;">​</a></h3><p>数列从 20 开始，每次减少 3，前四个数依次是什么？</p><p>知识点：p1-18 重复规律与数列初步。</p><details class="details custom-block"><summary>查看答案与讲解</summary><p><strong>答案：</strong> 20、17、14、11。</p><p><strong>推导步骤：</strong> 20 是第一个数，依次算 20−3＝17、17−3＝14、14−3＝11。</p><p><strong>易错提醒：</strong> 第一项已经给出，只需再减三次。</p></details>',84)])])}const c=e(p,[["render",o]]);export{g as __pageData,c as default};
